#!/usr/bin/env python3
"""Payment reconciliation tool.

Reads a CSV of transactions and prints a JSON summary of valid/failed counts
and total valid amount.
"""
import sys
import csv
import json
from datetime import datetime, timezone

def parse_timestamp(ts: str) -> datetime:
    """Parse an ISO-8601 timestamp into a UTC-aware datetime."""
    # datetime.fromisoformat handles the offset; convert to UTC for comparison.
    return datetime.fromisoformat(ts).astimezone(timezone.utc)

def load_rows(csv_path: str):
    with open(csv_path, newline="") as f:
        return list(csv.DictReader(f))

def dedupe_latest(rows):
    """Deduplicate rows by tx_id, keeping the row with the latest UTC timestamp.
    On exact timestamp ties, keep the row whose status is alphabetically first
    (FAILED < PENDING < VALID)."""
    best = {}
    for row in rows:
        tx_id = row["tx_id"]
        ts = parse_timestamp(row["timestamp"])
        status = row["status"]
        if tx_id not in best:
            best[tx_id] = (ts, status, row)
            continue
        cur_ts, cur_status, _ = best[tx_id]
        if ts > cur_ts:
            best[tx_id] = (ts, status, row)
        elif ts == cur_ts:
            # Choose the row with the alphabetically smaller status.
            if status < cur_status:
                best[tx_id] = (ts, status, row)
    return [entry[2] for entry in best.values()]

def summarize(rows):
    valid_count = 0
    failed_count = 0
    total_valid_amount = 0.0
    for row in rows:
        status = row["status"]
        amount = float(row["amount"])
        if status == "VALID":
            valid_count += 1
            total_valid_amount += amount
        elif status == "FAILED":
            failed_count += 1
        # PENDING rows are ignored.
    return {
        "total_valid_amount": round(total_valid_amount, 2),
        "valid_count": valid_count,
        "failed_count": failed_count,
    }

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python3 reconcile.py <path_to_csv>\n")
        sys.exit(1)
    csv_path = sys.argv[1]
    rows = load_rows(csv_path)
    deduped = dedupe_latest(rows)
    summary = summarize(deduped)
    # Print a single line of compact JSON.
    print(json.dumps(summary, separators=(",", ":")))

if __name__ == "__main__":
    main()
